async function ordinalCall(toolName,args,label){
const state=load('ordinalRate');
const weight=args.actions?.length??1;
if(weight>10)throw Error('Batch too large');
while(true){
 const now=Date.now();state.events=state.events.filter(e=>now-e.at<60000);
 let wait=Math.max(0,state.lastEnd+2000-now,state.cooldownUntil-now);
 let used=state.events.reduce((a,e)=>a+e.weight,0);
 for(const e of state.events){if(used+weight<=state.budget)break;used-=e.weight;wait=Math.max(wait,e.at+60000-now);}
 if(!wait)break;state.log.push({type:'pause',label,at:new Date().toISOString(),waitMs:wait});store('ordinalRate',state);
 await new Promise(r=>setTimeout(r,Math.min(wait,45000)));
}
const startedAt=new Date().toISOString();let result;
try{result=await tools[toolName](args);}catch(e){result={isError:true,exception:String(e)};}
const end=Date.now();state.events.push({at:end,weight});state.lastEnd=end;
const raw=JSON.stringify(result);const is429=/Too Many Requests|too_many_requests|status.{0,10}429|rate.limit.exceeded/i.test(raw);
if(is429){state.rateErrors++;state.budget=15;const retry=raw.match(/Retry-After[^0-9]*(\d+)/i);state.cooldownUntil=end+(retry?Number(retry[1])*1000:60000*2**Math.min(state.rateErrors-1,2))+2000;}
state.log.push({type:'call',label,tool:toolName,startedAt,endedAt:new Date(end).toISOString(),weight,is429,isError:!!result.isError});
store('ordinalRate',state);store('ordinalLastResponse',result);
if(is429)throw Error('429: reconcile after cooldown before retry');
return result;
}
